import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"恆","description":"焦氏易林注 - 恆","frontmatter":{"title":"恆","description":"焦氏易林注 - 恆"},"headers":[],"relativePath":"classics/jiaoyilin/032.md","filePath":"classics/jiaoyilin/032.md"}'),l={name:"classics/jiaoyilin/032.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="恆" tabindex="-1">恆 <a class="header-anchor" href="#恆" aria-label="Permalink to “恆”">​</a></h1><h3 id="恆-1" tabindex="-1">恆 <a class="header-anchor" href="#恆-1" aria-label="Permalink to “恆”">​</a></h3><h3 id="恆之乾" tabindex="-1">恆之乾 <a class="header-anchor" href="#恆之乾" aria-label="Permalink to “恆之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>登墀踒足，南行折角。長夜之室，不逢忠直。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《恆》象。震為足，兌折故踒足。震為南，艮為角，艮覆故折角，伏坤故曰夜、曰室。</p><h3 id="恆之坤" tabindex="-1">恆之坤 <a class="header-anchor" href="#恆之坤" aria-label="Permalink to “恆之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>燕雀衰老，悲鳴入海。憂在不飾，差池其羽。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>頡頑［當作頏］上下，寡位獨處。此仍用《恆》象。兌為燕雀，坤為老、為海，四五二句《詩邶風燕燕》文，乃莊薑送戴媯大歸於陳之詩，故曰寡位獨處，義與毛合。○鳴，宋元本作鴻，第三句作憂不在鄉，寡作在，均依汲古。</p><h3 id="恆之屯" tabindex="-1">恆之屯 <a class="header-anchor" href="#恆之屯" aria-label="Permalink to “恆之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>開閡除憂，伯自外來。忉忉無患，無心得歡。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坤為門，震為開、為除，坎為憂，在外故開門除憂。震為伯，伯自外來，言由外來內也。坎為患、為心，震樂故無。○無，汲古作之，依宋元本。心，宋元本作之，依汲古。</p><h3 id="恆之蒙" tabindex="-1">恆之蒙 <a class="header-anchor" href="#恆之蒙" aria-label="Permalink to “恆之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>郊耕釋耜，有所疑止，空虛無子。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為郊，震為耕、為耜，坎為疑，坤為虛。釋耜，言輟耕也，故因疑而止。坤為虛，震為子，坤亡故無子。○郊，宋元本作效，耜作秬，均依汲古。釋，汲古作擇，依宋本。</p><h3 id="恆之需" tabindex="-1">恆之需 <a class="header-anchor" href="#恆之需" aria-label="Permalink to “恆之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>張牙切齒，齗怒相視。禍起蕭牆，牽引吾子。患不可解，憂驚吾母。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>互兌為牙齒，兌剛魯故曰齗怒。離為視，故曰齗怒相視。離為禍，伏艮為牆、為牽引，坎為患、為憂，伏坤為母。○齗怒相視，宋元本作斷怒相及，依汲古。齗齗，爭辯貌。</p><h3 id="恆之訟" tabindex="-1">恆之訟 <a class="header-anchor" href="#恆之訟" aria-label="Permalink to “恆之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>履不容足，南山多棘。毋出房闥，乃無病疾。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>伏《明夷》。震為足、為履、為南，坎為棘、為室，故曰房闥，坎隱伏，故曰毋出。坎為病疾，震解故無。○闥，汲古作閨，依宋元本。</p><h3 id="恆之師" tabindex="-1">恆之師 <a class="header-anchor" href="#恆之師" aria-label="Permalink to “恆之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>牛騂無子，鳴於大野。申後陰微，還歸其母。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>騂，《玉篇》雲:馬赤黃也。坤為牛、為黃，故曰騂牛。震為子，坤殺，故曰子。坤為野，震為鳴，故曰鳴於大野。坤為後、為母，震為歸，周幽王後，申國女，幽王寵褒姒，廢申後，故曰遠歸其母。○三四句宋元本作&quot;申後陰微，罡歸其母&quot;，茲依汲古。</p><h3 id="恆之比" tabindex="-1">恆之比 <a class="header-anchor" href="#恆之比" aria-label="Permalink to “恆之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>龍生於淵，因風昇天。章虎炳文，為禽敗軒。發輗溫谷，暮宿昆侖。終身無患，光精照耀，不被禍難。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>首二句兼用《恆》象。震為龍、為生，兌為淵，故曰龍生於淵。巽為風，乾為天，龍在天上，故曰因風昇天。比坤為文，艮為虎，震為車，震覆故曰敗軒。禽者，田獵也。輗，轅端持衡者。坤為車，一陽在坤上若轅端衡木，蓋艮象也。《水經註》渭水右有溫谷，然此溫谷即暘谷。《書》宅嵎夷曰暘谷。《淮南子》日出於暘谷，言發輗東海，夕至侖昆［當作昆侖］也。坤為暮，艮為昆侖，坤為身，艮為終、為光明，坎為患難。○升，宋元本作身，禽作兇，光作充，均依汲古。照，元本作照，依宋本及汲古。禍，汲古作患，與上患字復，依宋元本。</p><h3 id="恆之小畜" tabindex="-1">恆之小畜 <a class="header-anchor" href="#恆之小畜" aria-label="Permalink to “恆之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>既嫁宜吉，出入無咎。三聖並居，國安無災。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為嫁、為出，巽為入，坎為聖，震數三，故曰三聖。坤為國，震樂故無咎災。○咎，宋元本作憂，依汲古。</p><h3 id="恆之履" tabindex="-1">恆之履 <a class="header-anchor" href="#恆之履" aria-label="Permalink to “恆之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>北陸陽伏，不知白黑。君子傷讒，正害善人。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坎為北，陽陷陰中，故曰陽伏。《左傳》：&quot;日行北陸而藏冰&quot;，言天寒也。坎為黑，巽為白，巽坎皆為伏，故不知。艮為君子，正反震故曰傷讒。○白黑，汲古作黑白，依宋本。</p><h3 id="恆之泰" tabindex="-1">恆之泰 <a class="header-anchor" href="#恆之泰" aria-label="Permalink to “恆之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>一身兩頭，近適二家，亂不可治。坤為身，乾數一，故曰一身。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾為頭，坤數二，故曰兩頭。伏艮為家，坤為亂。○近，汲古作延，依宋元本。</p><h3 id="恆之否" tabindex="-1">恆之否 <a class="header-anchor" href="#恆之否" aria-label="Permalink to “恆之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>牝馬牡駒，歲字不休。君子衣服，利得有餘。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾坤合體故曰牝牡，故歲字不休，字，息也。乾為歲，互艮為君子，巽為利，乾為衣。○牡駒，宋元作牝駒，依汲古。字，汲古作孳，依宋元本。</p><h3 id="恆之同人" tabindex="-1">恆之同人 <a class="header-anchor" href="#恆之同人" aria-label="Permalink to “恆之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>南行懷憂，破其金輿。安坐故廬，乃無災患。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為南，坤為憂患、為車，乾為金，故曰金輿。坎為破、為室廬。○災，依宋元本，汲古作殃。</p><h3 id="恆之大有" tabindex="-1">恆之大有 <a class="header-anchor" href="#恆之大有" aria-label="Permalink to “恆之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>憂人之患，履傷浮願。為身禍殘，篤心自守，與喜相抱。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為憂患，震為履，震覆故曰履傷。坤為身、為禍，坎心，艮為抱。第二句或有訛字，或謂浮願猶不及料也。願，汲古作顏，依宋元本。</p><h3 id="恆之謙" tabindex="-1">恆之謙 <a class="header-anchor" href="#恆之謙" aria-label="Permalink to “恆之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>鹹陽辰巳，長安戌亥。丘陵生心，非魚暿小？梢員芩，終無兇咎。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>《謙》震、坎、艮三陽俱備，震乾初坎乾中，艮乾上三陽成乾，故曰鹹陽。闢卦乾居辰巳，故曰鹹陽辰巳。震為長，坤為安，故曰長安。闢卦坤居戌亥，故曰長安戌亥。坎先天位西，坤為都邑。鹹陽，長安，西方都邑也。艮為丘陵，坤為魚、為水，言丘陵可避水不可得魚也。○水，宋元本訛不，依汲古。按：《韻補》雲亥音喜，引《易林》將戍系亥，陽藏不起為證，此處亦然，韻補說是也。</p><h3 id="恆之豫" tabindex="-1">恆之豫 <a class="header-anchor" href="#恆之豫" aria-label="Permalink to “恆之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>不知何孫，夜來扣門。我慎外寢，兵戎且來。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮為孫，坎為夜，坤為門，艮手故曰扣門。外寢，外室也。艮為外、為寢，為刀兵。○寢，汲古訛寇，依宋元本。</p><h3 id="恆之隨" tabindex="-1">恆之隨 <a class="header-anchor" href="#恆之隨" aria-label="Permalink to “恆之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>昧旦不明，日暗無光。喪滅失常，使我心傷。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為旦，兌為昧，故曰昧旦不明。艮為日、為光，兌嚮晦故無光。○日暗，依汲古，宋元本作暗我，我為夜之形訛字，疑原作暗夜無光，暗夜與昧旦為對文，今姑從汲古。</p><h3 id="恆之蠱" tabindex="-1">恆之蠱 <a class="header-anchor" href="#恆之蠱" aria-label="Permalink to “恆之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>江陰水側，舟楫破乏。狐不得南，豹無以北。雖欲會盟，河水絕梁。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>坤為大川，故曰江水。震為舟，兌毀故破乏。艮為狐、為豹，震為南，震反為艮則北矣，艮止故不得南。北艮為梁，兌折故梁絕。○狐，宋元本作孤，依汲古。北，元本訛比，依宋本、汲古。絕梁，汲古作梁絕，依宋元本，梁與盟韻。</p><h3 id="恆之臨" tabindex="-1">恆之臨 <a class="header-anchor" href="#恆之臨" aria-label="Permalink to “恆之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>神之在醜，破逆為咎。不利西南，商人休止。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為神，先天居醜方，又臨為醜月卦，故曰神之在醜。兌為破，易至於八月有兇，言至未遯，醜未沖，故曰破逆為咎、曰不利西南。西南，遯未也。震為商人，因逆破故休止。○第四句宋元本作人休止後，依汲古。</p><h3 id="恆之觀" tabindex="-1">恆之觀 <a class="header-anchor" href="#恆之觀" aria-label="Permalink to “恆之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>然諾不行，欺天誤人。使我露宿，夜歸溫室。神怒不直，鬼擊其目。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>欲求福利，適反自賊。震為言，震覆，故曰然諾不行、曰欺天誤人。艮為天、為室，坤為宿、為夜，艮為火，故曰溫室。伏震為神、為怒，坤為鬼，艮為目，艮手故曰鬼擊其目。艮為求，巽為利、為賊。○天，汲古作訟，露作虛，均依宋元本。</p><h3 id="恆之噬嗑" tabindex="-1">恆之噬嗑 <a class="header-anchor" href="#恆之噬嗑" aria-label="Permalink to “恆之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>攘臂極肘，怒不可止。狼戾愎佷，無與為市。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為臂肘。極，放也。《儀禮大射》&quot;贊設決朱極三&quot;註：極，放也，極肘，即放肘也。震為怒，艮為狼，巽為市，巽伏，故曰無與為市。○極，汲古作拯，依宋元本。愎，宋本訛復，依元本、汲古。佷，汲古作狠，依宋元本。</p><h3 id="恆之賁" tabindex="-1">恆之賁 <a class="header-anchor" href="#恆之賁" aria-label="Permalink to “恆之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>販馬買牛，會值空虛。利得尠少，流連為憂。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>離為牛，震為馬、為商旅，故曰販買。離為空虛，巽為利，巽伏，故利得鮮少。坎為憂，艮止故曰流連。○買，宋元本作賣，依汲古。</p><h3 id="恆之剝" tabindex="-1">恆之剝 <a class="header-anchor" href="#恆之剝" aria-label="Permalink to “恆之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>高樓陸處，以避風雨。深室邃宇，君安其所。牝雞之晨，為我利福，請求弗得。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>此用《恆》象。伏坤為重故為樓，巽為高故曰高樓。坤為陸，故曰陸處。巽為風，兌為水，故亦為雨。巽為伏，故曰以避風雨。艮為堂宇，下乘坤故曰深邃。震為君，艮為安，故曰君安其所。震為晨，巽為雞、為利，艮為請求，坤虛故弗得。○之晨，元本作之息，汲古作司晨，依宋本。福請求，宋元本作弗求得，茲依汲古。</p><h3 id="恆之復" tabindex="-1">恆之復 <a class="header-anchor" href="#恆之復" aria-label="Permalink to “恆之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>阿衡服箱，太乙載行。逃時厯舍，所之吉昌。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>《天官書》：&quot;北斗帝車運乎中央&quot;，《晉書天文志》：&quot;北斗杓三星為玉衡&quot;，衡，平也，轅端橫木也。坤為平、為方、為車箱，故曰阿衡服箱。《詩》：&quot;睆彼牽牛，不以服箱&quot;，《毛傳》：&quot;服，牝服也；箱，大車之箱也&quot;，疏：牝服長八尺謂較也，今俗為平較，兩較之內謂之箱。按：大車牛車兩轅，今車兩邊之牆古謂之較，兩較之中即為箱，以其中虛故名牝服，茲曰阿衡服箱。與太乙並稱，則阿衡指玉衡，服箱指牽牛，言太乙居中御鬥牛以行也。震為君，故曰太乙。太乙，即北辰極尊，象君臣復出入無疾，故所之吉昌。○之，汲古作求，非，依宋元本。逃，疑為巡之訛。</p><h3 id="恆之無妄" tabindex="-1">恆之無妄 <a class="header-anchor" href="#恆之無妄" aria-label="Permalink to “恆之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>飛來之福，入我嘉室，以安吾國。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>乾為福，震為飛，巽為入，艮為室、為國。○嘉，汲古作居，依宋本。</p><h3 id="恆之大畜" tabindex="-1">恆之大畜 <a class="header-anchor" href="#恆之大畜" aria-label="Permalink to “恆之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>不孝之患，子孫為殘。老耄莫養，獨坐室垣。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>巽為孝，二至四巽覆，故曰不孝。伏坤為患，震為子，艮為孫，皆履乾上，而兌毀折故曰殘。乾為老，坤為養，坤伏故莫養。艮為垣、為坐、為獨。○子孫為殘，宋元本作子為母殘，茲依汲古。</p><h3 id="恆之頤" tabindex="-1">恆之頤 <a class="header-anchor" href="#恆之頤" aria-label="Permalink to “恆之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>南過棘門，鉤裂我冠。斷衣傷襦，使君恨憂。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>通《大過》。乾為南、為門，互大坎故曰棘門。艮為冠、為鉤，兌毀故冠裂。乾為衣襦，巽下斷，故斷衣傷襦。乾為君，坤為恨憂。○鉤，汲古作駒，依宋本。斷衣，宋元本作鬬之，茲依汲古。</p><h3 id="恆之大過" tabindex="-1">恆之大過 <a class="header-anchor" href="#恆之大過" aria-label="Permalink to “恆之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>重弋射隼，不知所定。質疑蓍龜，孰可避之。明神答報，告以肌如，宜利止居。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>以繩系矢而射曰弋，正反巽故曰重弋。伏艮為隼，震為射，正反震故不能定射的在何所也。震為蓍，艮為龜，坤為疑，震言故曰質疑。震為往，正反震故曰孰可避之。震為神，艮為明，上艮為反震故曰答報。艮為止，巽為肌。肌，蟲名，《爾雅釋蟲》：&quot;密肌，繼英，皆蟲名&quot;，註雲未詳，茲曰止居或密肌為蟄伏之蟲，正巽象也。○弋，宋元本作或，汲古作卒，之訛六，均依《困》之《蹇》校。肌如，汲古作犧牲，依宋元本。宋元本無末句，依汲古。</p><h3 id="恆之坎" tabindex="-1">恆之坎 <a class="header-anchor" href="#恆之坎" aria-label="Permalink to “恆之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>麟麑鳳雛，安樂無憂。捕魚河海，利逾徙居。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>伏離為文，故曰麟鳳。艮亦為獸、為鳥，艮少故曰麑曰雛。麑，鹿子也。坎為憂，震樂，故無憂。伏巽為魚、為利，艮為捕，坎為河海，故曰捕魚河海。艮為居，震行故曰徙居。○雛，宋元本作稚，徙作從，均依汲古。</p><h3 id="恆之離" tabindex="-1">恆之離 <a class="header-anchor" href="#恆之離" aria-label="Permalink to “恆之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>新田宜粟，上農得榖。君子懷德，以千百祿。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>離為新，伏艮為田，二歲為新田，巽為粟、為榖，中爻正反巽故曰宜粟、曰得榖。伏艮為君子、為求，故曰千。震為百、為祿。○二三句宋元本作&quot;君子惟德，千百以福&quot;，茲依汲古。</p><h3 id="恆之鹹" tabindex="-1">恆之鹹 <a class="header-anchor" href="#恆之鹹" aria-label="Permalink to “恆之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>簪短帶長，幽思苦窮。瘠蠡小瘦，以病之癃。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《復》之《節》。第四句宋元本癃作隆，依汲古。蠡，元本作蟸，非，癃，創也。艮象，言小瘦之故因病癃也。</p><h3 id="恆之恆" tabindex="-1">恆之恆 <a class="header-anchor" href="#恆之恆" aria-label="Permalink to “恆之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝所生，伏羲之宇。兵刃不至，利以居止。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為帝、為玄黃，故曰黃帝。坤為牛，坤伏，故曰伏羲。羲，犧同，牛牲也。艮為兵刃，艮覆故曰至。巽為利。○宇，宋本訛宗，依元本、汲古。刃，宋元本作刀，依汲古。</p><h3 id="恆之遯" tabindex="-1">恆之遯 <a class="header-anchor" href="#恆之遯" aria-label="Permalink to “恆之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>爭訟之門，不可與鄰。出入有為，憂生我心。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為言，艮亦為言，兌為口，二至四兌反，與乾言相背，故曰爭訟，義本《夬九四》也。艮為門，伏震為出，巽為入，伏坤為憂、為心。○心，汲古作患，依宋元本。</p><h3 id="恆之大壯" tabindex="-1">恆之大壯 <a class="header-anchor" href="#恆之大壯" aria-label="Permalink to “恆之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>朽根枯株，不生肌膚。病在心腹，日以焦枯。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏巽為木、為隕落，故曰朽根枯株。艮為肌膚，上卦艮覆，故肌膚不生。伏坤為心腹、為病，巽隕故枯。按：壯者，傷也，故林詞如此而象則用伏。○腹，汲古作腸，焦作燋，均依宋元本。焦枯，宋元本作焦勞，依汲古協。</p><h3 id="恆之晉" tabindex="-1">恆之晉 <a class="header-anchor" href="#恆之晉" aria-label="Permalink to “恆之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>雨師娶婦，黃巖季子。成禮既婚，相呼南去。潤澤田裡，年歲大喜。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>此用恆伏象。兌為雨，坤為師，巽為婦，卦六爻皆有應予，易所謂婚媾也，故曰雨師娶婦。震為黃，艮為巖、為季子，故曰黃巖季子。坤為禮，艮為成，震巽為夫婦，故曰成禮既婚。震為呼、為南，兌為潤澤，坤為田裡、為年歲。震為喜，言田裡得雨澤，年歲豐熟而大喜也。元本舊註：《博物志》太公為灌壇令，武王夢婦人當道夜哭，問之曰：我是東海神女，嫁於西海神童，我行必有風雨雲雲。按：此註於林詞不甚合，恐別有故實，為今所不能考。○南去、潤澤田裡，依《井》之《坤》宋元本校，各本去作上，潤作膏，田裡作下圭。子，汲古作女，依宋元本。</p><h3 id="恆之明夷" tabindex="-1">恆之明夷 <a class="header-anchor" href="#恆之明夷" aria-label="Permalink to “恆之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>冬採薇蘭，地凍堅難。利走室北，暮無所得。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎為冬，震為薇蘭。坤為地，坎為凍、為險難，為室、為北，震行故曰利走室北。坤為暮，坤虛故無得。○薇，宋元本作微，依汲古。室，宋本、汲古作失，依元本。</p><h3 id="恆之家人" tabindex="-1">恆之家人 <a class="header-anchor" href="#恆之家人" aria-label="Permalink to “恆之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>昧之東域，誤過虎邑。失我熊胔，飢無所食。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《恆》象。震為東，兌為昧，伏艮為虎、為邑、為熊，伏坤為失、為虛，故為飢。○熊胔，依宋元本，汲古作熟羆，非。熊胔，熊肉也。</p><h3 id="恆之睽" tabindex="-1">恆之睽 <a class="header-anchor" href="#恆之睽" aria-label="Permalink to “恆之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>日暮閉目，隨陽休息。箕子以之，乃受其福。舉首多言，必為悔殘。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>離為日、為目，坎為閉、為暮，故曰日暮閉目。離為陽，兌嚮晦宴息，故曰休息。兌為口舌，故曰箕。坎為首，坎上下兌口故曰多言。○首，依宋元本，汲古作事。箕星司口舌。</p><h3 id="恆之蹇" tabindex="-1">恆之蹇 <a class="header-anchor" href="#恆之蹇" aria-label="Permalink to “恆之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>蓼蕭瀼瀼，君子龍光。鳴鸞雍雍，福祿來同。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>蓼蕭，《小雅》篇名，天子燕諸侯之詩。龍，寵也。為龍、為光，和鸞雝雝，萬福攸同，皆詩語。遇卦恆下巽為蓼蕭，震為龍、為鳴，鸞為雍雍，乾為福祿。○雍雍，汲古作噰噰，依宋元本，字與毛詩異。</p><h3 id="恆之解" tabindex="-1">恆之解 <a class="header-anchor" href="#恆之解" aria-label="Permalink to “恆之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>鳥飛無翼，兔走折足。雖不會同，未得醫工。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為鳥、為兔、為翼、為足，坎折巽寡髪，故無翼，坎蹇故折足。坎為醫，巽為工，巽伏坎隱故不得，言不得醫折足之患也。○會同，汲古作同會，醫工作利達，均依宋元本。</p><h3 id="恆之損" tabindex="-1">恆之損 <a class="header-anchor" href="#恆之損" aria-label="Permalink to “恆之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>五勝相賊，火得水息。精光消滅，絕不能續。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>卦兌金，克震木，震木克坤土，而兌又為水，艮又為火，故火得水而息滅也。元本註五勝者，言五行相勝之義。伏巽為賊，卦數五，故曰五勝相賊。艮為光，坤消兌絕。○能，宋元作長，依汲古。</p><h3 id="恆之益" tabindex="-1">恆之益 <a class="header-anchor" href="#恆之益" aria-label="Permalink to “恆之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>東資齊魯，得騂大馬。便辟能言，巧賈善市。八鄰並戶，請火不與。人道閉塞，鬼守其宇。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為東，巽為齊，伏兌為魯。震為馬，伏乾為赤，故曰騂。騂，赤色也。正反震，故曰便辟能言。巽為賈市，坤為戶，卦數八，艮亦為戶，數亦八，故曰八鄰並戶。並屏同，並戶即閉戶也。艮為火，下乘坤水，故不得火。坤為道路、為閉塞，孟子：請火於鄰無弗與者。今八鄰閉戶不與。故曰人道閉塞。坤為鬼，艮為守、為宇，故曰鬼守其宇。巧賈善市，汲古作市人善賈，八鄰作鄰人，守作祟，均依宋元本。</p><h3 id="恆之夬" tabindex="-1">恆之夬 <a class="header-anchor" href="#恆之夬" aria-label="Permalink to “恆之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>爭雞失羊，亡其金囊。利不得長，陳蔡之患，賴楚以安。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>遇卦互兌為羊，巽為雞，而兌巽相反覆，故得雞則失羊，得羊必失雞，不可得兼也。坤為囊，坤伏故亡。乾金巽利，震為陳、為蔡、為楚，伏坤為患。《史記孔子世家》：陳蔡聞楚聘孔子，懼，發徒役圍孔子，不得行，絕糧，於是使子貢至楚，楚昭王興師迎孔子，然後得免。</p><h3 id="恆之姤" tabindex="-1">恆之姤 <a class="header-anchor" href="#恆之姤" aria-label="Permalink to “恆之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>九登十陟，馬跌不前。管子佐之，乃能上山。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震數九，坤數十，震為登、為陟、為馬，坤失，故曰馬跌不前。震為竹，故曰管子。乾為山，言管子佐齊桓乃能霸天下也。○首句元本作十登九涉，依宋本、汲古。</p><h3 id="恆之萃" tabindex="-1">恆之萃 <a class="header-anchor" href="#恆之萃" aria-label="Permalink to “恆之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>東鄰愁苦，君亂天紀。日貪祿寵，必受其咎。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>通《大畜》。震為東鄰，坤為愁苦、為亂，乾為君、為天、為祿寵。義多未詳，或指紂。○日，宋元本作甘，依汲古。宋元本下有&quot;意合志同，內外相從，見吾伯公&quot;三句，與上文義相反，斷為衍文，否則只用此三句象甚合，語亦較有味，惟不能並用。</p><h3 id="恆之升" tabindex="-1">恆之升 <a class="header-anchor" href="#恆之升" aria-label="Permalink to “恆之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>三狸捕鼠，遮遏前後。死於環城，不能脫走。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《遯》。○環城，宋元本作壞城，汲古作外問，依《明夷》之《頤》校。</p><h3 id="恆之困" tabindex="-1">恆之困 <a class="header-anchor" href="#恆之困" aria-label="Permalink to “恆之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>虎狼爭強，禮義不行。兼吞其國，齊魯無王。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>上兌為虎狼，正反兌故曰爭強。兌為吞、為魯，巽齊，震為王，震伏故曰齊魯無王，言秦併合六國，致列國無主也。</p><h3 id="恆之井" tabindex="-1">恆之井 <a class="header-anchor" href="#恆之井" aria-label="Permalink to “恆之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>五嶽四瀆，合潤為德。行不失理，民賴恩福。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏艮為山嶽，巽卦數五，故曰五嶽。坎為江河，巽後天數四，故曰四瀆。坎為合、為潤、為眾，故曰民伏。震為恩福。○恩，宋元本作息，依汲古。</p><h3 id="恆之革" tabindex="-1">恆之革 <a class="header-anchor" href="#恆之革" aria-label="Permalink to “恆之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>六月種黍，歲晚無雨。秋不宿酒，神先其所。先困後通，與福相從。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。坎為月，數六，震為黍，故曰六月種黍。坎為雨、為暮，坤為歲，坤虛故無雨。兌為秋，坎為酒。宿，肅也。《儀禮》&quot;宿屍&quot;註：宿與《曲禮》&quot;主人肅客&quot;之肅同。又《禮祭統》&quot;先期旬有一日，宮宰宿夫人&quot;註：宿讀為肅，戎也，茲雲秋不宿酒，言無黍不能釀，至秋祭不能先期戒備酒醴也。震為神，坤失，故曰失所。坎為困，震為通、為後、為從。震為福，正反震，故曰相從。○從，宋元本作逢，依汲古。</p><h3 id="恆之鼎" tabindex="-1">恆之鼎 <a class="header-anchor" href="#恆之鼎" aria-label="Permalink to “恆之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>騋牝龍身，日馭三千。南上蒼梧，與福為婚。道里夷易，身安無患。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《比》。</p><h3 id="恆之震" tabindex="-1">恆之震 <a class="header-anchor" href="#恆之震" aria-label="Permalink to “恆之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>出入休居，安止無憂。上室之歡，虎為季殘。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震出，伏巽為入，艮止，故曰休居、曰安止。艮為室、為虎、為季。○無，宋元本作相，歡作權，均依汲古。虎，汲古作虐，依宋元本。第三四句費解，疑有訛字。</p><h3 id="恆之艮" tabindex="-1">恆之艮 <a class="header-anchor" href="#恆之艮" aria-label="Permalink to “恆之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>南山昊天，刺政閔身。疾病無辜，背憎為仇。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《復》。○閔，宋元本作關，依汲古。憎，宋元本作增，非，依元本、汲古。</p><h3 id="恆之漸" tabindex="-1">恆之漸 <a class="header-anchor" href="#恆之漸" aria-label="Permalink to “恆之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>蒼耳東從，道頓跂踦。日辰不良，病為祟禍。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>元本註：蒼耳，馬也。《遯》之《小過》曰騎騅與蒼蓋即蒼耳。坎為耳，伏震為東、為青，故曰蒼耳。艮為道，坎蹇故曰跂踦。離為日，艮為時，故曰日辰，坎破故不良。坎為病。○第二句元本作潼頓東徙，非，依宋本、汲古。</p><h3 id="恆之歸妹" tabindex="-1">恆之歸妹 <a class="header-anchor" href="#恆之歸妹" aria-label="Permalink to “恆之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>兄徵東燕，弟伐遼西。大克勝還，封居河間。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為東、為兄，兌為燕，故曰兄徵東燕。兌為西，坎為弟，坎水，故曰弟伐遼西。坎為河。○居，宋元本作君，依汲古。</p><h3 id="恆之豐" tabindex="-1">恆之豐 <a class="header-anchor" href="#恆之豐" aria-label="Permalink to “恆之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>播輪折輻，馬不得行。豎牛之讒，賊其父兄。布衣不傷，終身無患。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>互大坎為輪輻，兌毀，故曰播輪折輻。震為馬，坎陷故馬不行。離為牛，伏艮為豎，正反兌口，故曰豎牛之讒。震為兄、為父，坎為賊。○輪，宋元本訛輸，衣作裘，患作殘，均依汲古。豎牛事在《左傳成十六年》，見前。</p><h3 id="恆之旅" tabindex="-1">恆之旅 <a class="header-anchor" href="#恆之旅" aria-label="Permalink to “恆之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>駕之南海，晨夜不止。君子勞罷，僕夫憔苦。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為南，兌為海，震車，故曰駕之南海。震為晨，坎為夜，艮為君子、為僕夫，坎為勞罷、為苦。○夫憔，宋元本作使燋，依汲古。</p><h3 id="恆之巽" tabindex="-1">恆之巽 <a class="header-anchor" href="#恆之巽" aria-label="Permalink to “恆之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>怨蝨燒被，忿怒生禍。褊心作難，意如為亂。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲，故曰蝨。震為被，離火，震伏不見，故曰燒被。兌為附決、為剛魯，故曰怨、曰忿怒。伏坎為心，坎陷，故曰褊心。意如，季平子名也。《左傳昭二十五年》：&quot;公伐季氏&quot;，褊心，謂昭公也，後公卒，為季氏所逐，故曰意如作亂。○首句汲古作怨重被燒，難作事，均依宋元本。</p><h3 id="恆之兌" tabindex="-1">恆之兌 <a class="header-anchor" href="#恆之兌" aria-label="Permalink to “恆之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>張狂妄行，竊食盜糧。狗吠非主，嚙傷我足。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。互震為張狂、為行，坎為盜竊，震為糧，故曰竊食盜糧。艮為狗，兌為吠，震為主，震覆故曰非主。兌為嚙，震為足，兌毀故傷足。○盜糧，汲古作稻粱，茲依宋元本。</p><h3 id="恆之渙" tabindex="-1">恆之渙 <a class="header-anchor" href="#恆之渙" aria-label="Permalink to “恆之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>警蹕戒道，先驅除咎。王后親桑，以率群功，安我祖宗。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>首二句皆震象。艮為道、為王，巽為桑，艮為安、為祖。○咎，宋元本作害，依汲古。</p><h3 id="恆之節" tabindex="-1">恆之節 <a class="header-anchor" href="#恆之節" aria-label="Permalink to “恆之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>門戶乏食，困死誰告。對門不通，安所歸急。積藏五穀，一華千葉，市賈有息。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為門戶，坎為困，互震為虛，故乏食。艮敗言，故困死誰告。二至五正反艮相對，故曰對門，艮止坎陷，故曰不通。不通則緩急難恃，故曰安所歸急。震為歸也。坎為積藏，卦數五，震為谷，故曰積藏五穀。震為旉、為華葉、為商賈，震生故曰息。○死，宋元本作無，安作莫，千作百，無第七句，均非，均依汲古。</p><h3 id="恆之中孚" tabindex="-1">恆之中孚 <a class="header-anchor" href="#恆之中孚" aria-label="Permalink to “恆之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>破敝復完，危者得安。鄉善無患，商人有息，利來入門。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>兌為破敝、為毀折，故為危。艮成終故復完而得安也。震為商人，巽為利入，艮為門。○首句宋元本作被蔽復貌，依汲古。患，汲古作損，依宋元本。鄉同向。</p><h3 id="恆之小過" tabindex="-1">恆之小過 <a class="header-anchor" href="#恆之小過" aria-label="Permalink to “恆之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>迭迭纍纍，如岐之室。一息十子，古公治邑。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為室，震為生、為息、為子，兌數十，故曰一息十子。震為公，艮為邑。按：《詩大雅》雲：&quot;古公亶父，陶復陶穴，未有家室&quot;，言古公初至岐，未有家室，暫陶覆陶穴而居。迭迭纍纍，穴居之狀，故曰如岐之室。○首句宋元本作壘壘壘壘，又岐作其，均依汲古。息，汲古作身，依宋元本。</p><h3 id="恆之既濟" tabindex="-1">恆之既濟 <a class="header-anchor" href="#恆之既濟" aria-label="Permalink to “恆之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>三嫗治民，不勝其任。兩馬爭車，敗壞家室。</p><h3 id="恆之未濟" tabindex="-1">恆之未濟 <a class="header-anchor" href="#恆之未濟" aria-label="Permalink to “恆之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>蔽鏡無光，不見文章。少女不市，棄於相望。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>離為鏡、為光，坎為蔽，故無光，故不見文章。離為文也。○第四句宋元本作棄其卻王，茲依汲古，未知孰是。</p>',320)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
